"""Fibonacci Number — bottom-up iteration.

The naive recursion is O(2^n); rolling two variables forward is linear and needs
no memo table.

Time: O(n)   Space: O(1)
"""


class Solution:
    def fib(self, n: int) -> int:
        if n < 2:
            return n
        prev, current = 0, 1
        for _ in range(2, n + 1):
            prev, current = current, prev + current
        return current
